#include "AutoFit.h"
#include "Selection.h"
#include <iostream>
#include <random>
#include <stdexcept>
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
int main(){try{
 std::mt19937 random(2505);std::uniform_real_distribution<double> unit(0,1);for(int i=0;i<10000;++i){double duration=.001+unit(random)*3600;auto range=nova::SelectionRange::between((unit(random)*1.6-.3)*duration,(unit(random)*1.6-.3)*duration,duration);check(range.valid(duration),"selection bounds");range.move((unit(random)*2-.5)*duration,duration);check(range.valid(duration),"move bounds");range.resizeStart((unit(random)*2-.5)*duration,duration);check(range.valid(duration),"start handle bounds");range.resizeEnd((unit(random)*2-.5)*duration,duration);check(range.valid(duration),"end handle bounds");for(double sr:{8000.,44100.,48000.,96000.}){auto n=static_cast<int64_t>(std::ceil(duration*sr));auto span=nova::sampleSpan(nova::SelectionRange::between(range.start,range.end,n/sr),sr,n);if(!(span.count>0&&span.first>=0&&span.first+span.count<=n)){std::cerr<<"i="<<i<<" sr="<<sr<<" duration="<<duration<<" actual="<<n/sr<<" start="<<range.start<<" end="<<range.end<<" length="<<range.length()<<" first="<<span.first<<" count="<<span.count<<'\n';throw std::runtime_error("sample span bounds");}}}
 auto later=nova::SelectionRange::between(125.25,126.75,180);auto span=nova::sampleSpan(later,48000,8640000);check(span.first==6012000&&span.count==72000,"region after old 15-second limit");auto reverse=nova::SelectionRange::between(48,47,60);check(reverse.start==47&&reverse.end==48,"reverse drag");auto huge=nova::SelectionRange::between(15,50,60);check(huge.start==15&&huge.end==18,"explicit 3-second cap");auto invalid=nova::SelectionRange::between(NAN,1,10);check(invalid.length()==0,"nonfinite rejected");
 nova::PeakBuilder peaks;for(int i=0;i<513;++i)peaks.push(i==12?1.f:i==512?-.9f:0.f,0);peaks.finish();check(peaks.peaks.size()==3&&peaks.peaks[0].high==1&&peaks.peaks[2].low==-.9f,"streamed peaks preserve transient and partial block");
 nova::Sound selected;selected.sampleRate=48000;selected.left.resize(24000);selected.right=selected.left;for(int i=9600;i<24000;++i)selected.left[i]=selected.right[i]=.3f*std::sin(2*nova::pi*440*i/48000);auto exact=nova::makeTarget(selected,69,22050,false);check(exact.left.size()==11025,"selected duration preserved without 0.6-second padding");for(int i=0;i<4000;++i)check(std::abs(exact.left[i])<1e-8,"selection leading silence preserved");auto autoTrim=nova::makeTarget(selected,69);check(autoTrim.left.size()!=exact.left.size(),"legacy automatic trimming retained separately");
 std::cout<<"PASS: 10,000 selection/handle/scroll ranges, sample offsets, reverse drag, 3s cap, waveform extrema and selected-time preservation\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
